"""usage: emit_m1_ts.py loops_bank.json attacks_bank.json > src/chips/m1Data.ts"""
import sys, json
loops = json.load(open(sys.argv[1]))
attacks = json.load(open(sys.argv[2]))
g = lambda v: '%g' % v
print("""import type { D50Attack } from './historical.ts';

/**
 * Parametric descriptors for the Korg M1 model, generated by `tools/rom-analysis` from measurements of the M1's own
 * sample ROM (the user's dumps, read offline). Only a few averaged numbers per entry are kept: no sample, no
 * waveform table and no ROM byte is part of the package. Do not edit by hand: regenerate.
 */

/** steady-state spectra: relative amplitude of harmonics 1..16, averaged over the periodic frames of a cluster; brightest first */""")
print('export const M1_LOOPS: readonly (readonly number[])[] = [')
for l in loops:
    print('\t[' + ', '.join(g(v) for v in l['harmonics']) + '],')
print('];\n')
print('/** attack transients: partials [ratio to the pitch, amplitude, decay in s] and a noise burst, like `D50_ATTACKS` */')
print('export const M1_ATTACKS: readonly D50Attack[] = [')
for a in attacks:
    hs = ', '.join('[%s, %s, %s]' % (g(r), g(x), g(d)) for r, x, d in a['harmonics'])
    print("\t{ name: '%s', harmonics: [%s], noise: %s, noiseDecay: %s, duration: %s }," % (a['name'], hs, g(a['noise']), g(a['noiseDecay']), g(a['duration'])))
print('];')
